// A long, flowing stadium circuit: two proper straights joined by broad semicircle turns.
const straight=20, radius=16, trackLength=4*straight+Math.PI*2*radius, averageRadius=trackLength/(Math.PI*2);
function centerAt(t){let s=((t/(Math.PI*2)*trackLength)%trackLength+trackLength)%trackLength;
  if(s<2*straight){return new THREE.Vector3(-straight+s,0,-radius)}s-=2*straight;
  if(s<Math.PI*radius){const a=-Math.PI/2+s/radius;return new THREE.Vector3(straight+radius*Math.cos(a),0,radius*Math.sin(a))}s-=Math.PI*radius;
  if(s<2*straight){return new THREE.Vector3(straight-s,0,radius)}s-=2*straight;
